import { createClient } from '@supabase/supabase-js';
const supabaseUrl = import.meta.env?.VITE_SUPABASE_URL || 'https://your-project.supabase.co';
const supabaseAnonKey = import.meta.env?.VITE_SUPABASE_ANON_KEY || 'your-anon-key';
export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
    auth: {
        autoRefreshToken: true,
        persistSession: true,
        detectSessionInUrl: true,
    },
    realtime: {
        params: {
            eventsPerSecond: 10,
        },
    },
});
// Helper function to get tenant-aware Supabase client
export function getTenantClient(tenantId) {
    return createClient(supabaseUrl, supabaseAnonKey, {
        auth: {
            autoRefreshToken: true,
            persistSession: true,
            detectSessionInUrl: true,
        },
        db: {
            schema: 'public',
        },
        global: {
            headers: {
                'x-tenant-id': tenantId,
            },
        },
    });
}
// Row Level Security helper functions
export const withTenantPolicy = (tenantId) => ({
    'tenant_id': tenantId,
});
export const withUserPolicy = (userId) => ({
    'user_id': userId,
});
// Real-time subscription helper
export function subscribeToTable(table, event, callback, filter) {
    const subscription = supabase
        .channel(`${table}-changes`)
        .on('postgres_changes', {
        event,
        schema: 'public',
        table,
        filter,
    }, callback)
        .subscribe();
    return subscription;
}
// Storage helper
export const uploadFile = async (file, path, bucket = 'uploads') => {
    const { data, error } = await supabase.storage
        .from(bucket)
        .upload(path, file);
    return { data: data?.path || null, error: error?.message || null };
};
export const getPublicUrl = (path, bucket = 'uploads') => {
    const { data } = supabase.storage
        .from(bucket)
        .getPublicUrl(path);
    return data.publicUrl;
};
export default supabase;
